const fs = require('fs');
const path = require('path');

const ROOT_DIR = path.resolve(__dirname, '..');
const CLIENT_HTML_PATH = path.join(ROOT_DIR, 'client', 'click-to-edit.html');
const HTML2CANVAS_PATH = path.join(ROOT_DIR, 'client', 'html2canvas.min.js');
const DIST_DIR = path.join(ROOT_DIR, 'dist');

function escapeForInlineScript(str) {
  return JSON.stringify(str).replace(/<\//g, '<\\/');
}

function build() {
  if (!fs.existsSync(CLIENT_HTML_PATH)) {
    throw new Error(`Missing source file: ${CLIENT_HTML_PATH}`);
  }
  if (!fs.existsSync(HTML2CANVAS_PATH)) {
    throw new Error(`Missing dependency file: ${HTML2CANVAS_PATH}`);
  }

  fs.mkdirSync(DIST_DIR, { recursive: true });

  const rawHtml = fs.readFileSync(CLIENT_HTML_PATH, 'utf8');
  const html2canvasCode = fs.readFileSync(HTML2CANVAS_PATH, 'utf8');

  // Remove the external html2canvas script tag (bundle includes it directly)
  const withoutExternalH2c = rawHtml.replace(
    /<script[^>]*src=["'][^"']*html2canvas\.min\.js["'][^>]*>\s*<\/script>\s*/i,
    ''
  );

  // Extract <style class="cte-ui">...</style>
  const styleMatch = withoutExternalH2c.match(/<style\b[^>]*>([\s\S]*?)<\/style>/i);
  const styleCss = styleMatch ? styleMatch[1] : '';

  // Extract <script class="cte-ui">...</script> (last script block)
  const scriptRegex = /<script\b[^>]*>([\s\S]*?)<\/script>/gi;
  let lastScriptMatch = null;
  let m;
  while ((m = scriptRegex.exec(withoutExternalH2c)) !== null) {
    lastScriptMatch = m;
  }
  const clientScript = lastScriptMatch ? lastScriptMatch[1] : '';

  // Remaining HTML markup (between style and script)
  let htmlMarkup = withoutExternalH2c;
  if (styleMatch) {
    htmlMarkup = htmlMarkup.replace(styleMatch[0], '');
  }
  if (lastScriptMatch) {
    htmlMarkup = htmlMarkup.replace(lastScriptMatch[0], '');
  }
  htmlMarkup = htmlMarkup.replace(/<!--[\s\S]*?-->/g, '').trim();

  const devGuardFn = `
  function isDevOrigin() {
    if (window.__KBS_DEV_MODE__ || window.__CTE_FORCE__) return true;
    var proto = (window.location && window.location.protocol) || '';
    if (proto === 'file:') return true;
    var host = (window.location && window.location.hostname) || '';
    if (!host) return false;
    if (host === 'localhost' || host === '127.0.0.1' || host === '0.0.0.0' || host === '::1' || host === '[::1]') return true;
    if (host.endsWith('.local') || host.endsWith('.localhost')) return true;
    if (/^192\\.168\\.\\d{1,3}\\.\\d{1,3}$/.test(host)) return true;
    if (/^10\\.\\d{1,3}\\.\\d{1,3}\\.\\d{1,3}$/.test(host)) return true;
    if (/^172\\.(1[6-9]|2\\d|3[0-1])\\.\\d{1,3}\\.\\d{1,3}$/.test(host)) return true;
    return false;
  }`;

  const runtimeJs = `/*!
 * Click-to-Edit & Visual Inspector (Universal Client)
 * Generated by scripts/build-bundle.js
 */
;(function() {
  if (typeof window === 'undefined' || typeof document === 'undefined') return;
  if (window.__CTE_LOADED__) return;
${devGuardFn}
  if (!isDevOrigin()) return;
  window.__CTE_LOADED__ = true;

  var CTE_CSS = ${escapeForInlineScript(styleCss)};
  var CTE_HTML = ${escapeForInlineScript(htmlMarkup)};

  function runClientLogic() {
    if (window.__CTE_INITIALIZED__) return;
${clientScript}
  }

  function mountCte() {
    if (document.getElementById('cte-container')) {
      runClientLogic();
      return;
    }

    var styleEl = document.createElement('style');
    styleEl.className = 'cte-ui';
    styleEl.textContent = CTE_CSS;
    (document.head || document.documentElement).appendChild(styleEl);

    if (document.body) {
      document.body.insertAdjacentHTML('beforeend', CTE_HTML);
      runClientLogic();
    }
  }

  if (document.readyState === 'loading' || !document.body) {
    document.addEventListener('DOMContentLoaded', mountCte, { once: true });
  } else {
    mountCte();
  }
})();
`;

  const clientOutPath = path.join(DIST_DIR, 'click-to-edit.js');
  fs.writeFileSync(clientOutPath, runtimeJs, 'utf8');

  const bundleJs = `/*!
 * Click-to-Edit & Visual Inspector Universal Bundle (includes html2canvas)
 * Generated by scripts/build-bundle.js
 */
;(function() {
  if (typeof window === 'undefined' || typeof document === 'undefined') return;
  if (window.__CTE_LOADED__) return;
${devGuardFn}
  if (!isDevOrigin()) return;
  if (typeof window.html2canvas === 'undefined') {
    (function() {
${html2canvasCode}
    }).call(window);
  }
})();
${runtimeJs}
`;

  const bundleOutPath = path.join(DIST_DIR, 'click-to-edit.bundle.js');
  fs.writeFileSync(bundleOutPath, bundleJs, 'utf8');

  console.log('[click-to-edit] Built dist/click-to-edit.js (' + Buffer.byteLength(runtimeJs) + ' bytes)');
  console.log('[click-to-edit] Built dist/click-to-edit.bundle.js (' + Buffer.byteLength(bundleJs) + ' bytes)');
}

if (require.main === module) {
  build();
}

module.exports = { build };
